/* @lc app=leetcode id=2056 lang=kotlin */
class Solution { fun countCombinations(pieces: Array<String>, positions: Array<IntArray>): Int = pieces.size.let { n -> arrayOf(intArrayOf(0, 0), intArrayOf(1, 0), intArrayOf(-1, 0), intArrayOf(0, 1), intArrayOf(0, -1), intArrayOf(1, 1), intArrayOf(1, -1), intArrayOf(-1, 1), intArrayOf(-1, -1)).let { d -> List(n) { i -> (0..8).filter { k -> k == 0 || (pieces[i] == "rook" && k in 1..4) || (pieces[i] == "bishop" && k in 5..8) || (pieces[i] == "queen" && k in 1..8) }.flatMap { k -> (if (k == 0) 0..0 else 1..7).filter { dist -> (positions[i][0] + d[k][0] * dist) in 1..8 && (positions[i][1] + d[k][1] * dist) in 1..8 }.map { dist -> intArrayOf(k, dist) } } }.let { allMoves -> DeepRecursiveFunction<Pair<Int, List<IntArray>>, Int> { (idx, current) -> if (idx == n) (1..8).all { t -> current.mapIndexed { i, m -> (positions[i][0] + d[m[0]][0] * minOf(t, m[1])) * 9 + (positions[i][1] + d[m[0]][1] * minOf(t, m[1])) }.let { pos -> pos.distinct().size == n } }.let { if (it) 1 else 0 } else allMoves[idx].sumOf { callRecursive(idx + 1 to current + it) } }.callRecursive(0 to emptyList()) } } } }